CREATE EXTERNAL TABLE dbo.departments_ext_table
(
    DEPARTMENT_ID INT,
    DEPARTMENT_NAME VARCHAR(100),
    MANAGER_ID INT,
    LOCATION_ID INT
)
WITH (
    LOCATION = 'inputdata/departments.csv',
    DATA_SOURCE = raw_Ext_source_practice,
    FILE_FORMAT = external_csv_file
);

DROP EXTERNAL TABLE  dbo.departments_ext_table;



SELECT *
FROM dbo.departments_ext_table;

  CREATE EXTERNAL DATA SOURCE raw_Ext_source_practice
    WITH
    (
        LOCATION = 'https://azuresynapse05.blob.core.windows.net/externaldatasource',
        CREDENTIAL = SynapseCreds
    );





SELECT * FROM 
OPENROWSET
(
    BULK 'inputdata/departments.csv',
    DATA_SOURCE = 'raw_Ext_source_practice',
    FORMAT='CSV',
    PARSER_VERSION = '2.0',
    HEADER_ROW = TRUE
) AS QUERY1;

CREATE EXTERNAL FILE FORMAT external_parquet_file
WITH (
         FORMAT_TYPE = PARQUET,
         DATA_COMPRESSION = 'org.apache.hadoop.io.compress.SnappyCodec'

    );

CREATE EXTERNAL FILE FORMAT external_csv_file
WITH (
         FORMAT_TYPE = DELIMITEDTEXT,
         FORMAT_OPTIONS(
            FIELD_TERMINATOR = ''
         )

    );
